import React, { useState, useEffect, useMemo, useRef, useLayoutEffect } from "react";
import { api, hasBackend, setToken, syncHealth } from "./api.js";

// Lightweight SECTION-level error boundary. The app has a full-page boundary at the root, but a render error
// in one panel (e.g. a rare data edge case in the draft recap/superlatives) shouldn't take down the entire
// page — the user loses access to everything else in the hub. Wrap a self-contained section in <Boundary>
// and, if it throws during render, that section shows a compact inline fallback while the rest of the page
// keeps working. `label` names the section in the fallback; `fallback` optionally overrides the message.
class Boundary extends React.Component {
  constructor(props) { super(props); this.state = { failed: false, msg: "" }; }
  static getDerivedStateFromError(error) {
    let msg = (error && error.message) ? String(error.message) : "Unknown error";
    // Include the first meaningful stack frame (function name) — with minified builds this is a short symbol,
    // but combined with the message it narrows the crash to a specific function far faster than the message alone.
    try { const st = (error && error.stack) ? String(error.stack).split("\n").map((l) => l.trim()).filter((l) => /^at /.test(l))[0] : ""; if (st) msg += ` · ${st.replace(/^at /, "").split(" (")[0]}`; } catch (e) {}
    return { failed: true, msg };
  }
  componentDidCatch(error, info) { try { console.error(`[FDC] section "${this.props.label || "section"}" render error:`, error, info); } catch (e) {} }
  render() {
    if (this.state.failed) {
      if (typeof this.props.fallback === "function") return this.props.fallback(this.state.msg);
      if (this.props.fallback !== undefined) return this.props.fallback;
      return (
        <div className="mut" style={{ fontSize: 12.5, padding: "10px 12px", border: "1px solid var(--line)", borderRadius: 9, background: "var(--panel2)" }}>
          This {this.props.label || "section"} couldn't load. The rest of the page still works — try refreshing if it persists.
        </div>
      );
    }
    return this.props.children;
  }
}


/* ============================================================
   FANTASY DRAFT COMPASS — FULL PLATFORM PROTOTYPE
   Public site -> sign up -> season pass checkout (simulated) ->
   league library (persists via artifact storage) -> league setup ->
   live draft room (real simplified engine) -> admin console.

   SECURITY MODEL — READ BEFORE LAUNCH:
   This is a CLIENT-SIDE prototype. Every gate here (admin allowlist,
   paid/unpaid access, profile data, simulated payments) runs in the
   browser and is therefore BYPASSABLE by a determined user via dev tools.
   That is unavoidable for any browser-only app. For production these MUST
   be enforced on a SERVER you control: managed auth (Auth0/Clerk/Firebase),
   server-side admin + subscription checks on every protected request,
   payments via Stripe/PayPal (card data never touches your servers),
   and profile/payment data behind authenticated, authorized APIs only.
   The ADMIN_EMAILS list below is the *client* convenience gate; the real
   authority check must live server-side. Payments & auth here are SIMULATED.
   Sample 2026 projection data. 12-team leagues in this demo.
   ============================================================ */

