function Faq({ q, a }) {
  const [open, setOpen] = useState(false);
  return (
    <div className="panel" style={{ marginBottom: 8, padding: "12px 16px", cursor: "pointer" }} onClick={() => setOpen((o) => !o)}>
      <div style={{ display: "flex", justifyContent: "space-between", fontWeight: 600 }}>{q}<span className="mut">{open ? "−" : "+"}</span></div>
      {open && <div className="mut" style={{ fontSize: 13.5, marginTop: 8, lineHeight: 1.55 }}>{a}</div>}
    </div>
  );
}

/* ============================================================ AUTH + CHECKOUT */
// Landing screen for the link in a password-reset email. Deliberately its own component rather than a
// fifth mode inside AuthModal: it is reached from a URL with no prior state, it has a token to honour, and
// it should not offer "sign up" or "forgot username" alternatives while the user is mid-reset.
function ResetPasswordModal({ token, onClose, onDone }) {
  const [pw, setPw] = useState("");
  const [pw2, setPw2] = useState("");
  const [show, setShow] = useState(false);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState(null);
  const tooShort = pw.length > 0 && pw.length < 6;
  const mismatch = pw2.length > 0 && pw !== pw2;
  const ready = pw.length >= 6 && pw === pw2;

  const submit = async () => {
    if (!ready || busy) return;
    setErr(null); setBusy(true);
    try {
      const user = await api.resetPassword(token, pw);
      onDone(user);
    } catch (e) {
      setErr((e && e.data && e.data.error) || (e && e.message) || "Could not reset the password. Request a new link.");
    } finally { setBusy(false); }
  };

  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,.72)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 2147482000, padding: 16 }}>
      <div className="panel" style={{ width: 400, maxWidth: "100%", padding: 22 }}>
        <div className="disp" style={{ fontSize: 20, fontWeight: 700, marginBottom: 4 }}>Choose a new password</div>
        <div className="mut" style={{ fontSize: 12.5, marginBottom: 16, lineHeight: 1.5 }}>Pick something at least 6 characters. You'll be signed in as soon as it's saved.</div>
        <div style={{ position: "relative", marginBottom: 10 }}>
          <input className="gs" type={show ? "text" : "password"} autoFocus style={{ width: "100%", paddingRight: 62 }} placeholder="New password" value={pw}
            onChange={(e) => setPw(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") submit(); }} />
          <button onClick={() => setShow((v) => !v)} style={{ position: "absolute", right: 8, top: 7, background: "transparent", border: "none", color: "var(--mut)", fontSize: 11, cursor: "pointer", fontFamily: "inherit" }}>{show ? "Hide" : "Show"}</button>
        </div>
        <input className="gs" type={show ? "text" : "password"} style={{ width: "100%", marginBottom: 10 }} placeholder="Confirm new password" value={pw2}
          onChange={(e) => setPw2(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") submit(); }} />
        {tooShort && <div className="mut" style={{ fontSize: 11.5, marginBottom: 8 }}>A little longer — 6 characters minimum.</div>}
        {mismatch && <div style={{ color: "var(--red)", fontSize: 11.5, marginBottom: 8 }}>Those don't match.</div>}
        {err && <div style={{ color: "var(--red)", fontSize: 12, marginBottom: 10, lineHeight: 1.45 }}>{err}</div>}
        <button className="btn btn-gold" style={{ width: "100%", padding: 11 }} disabled={!ready || busy} onClick={submit}>{busy ? "Saving…" : "Save and sign in"}</button>
        <button className="btn-link" style={{ background: "none", border: "none", color: "var(--mut)", fontSize: 11.5, cursor: "pointer", fontFamily: "inherit", padding: 0, display: "block", margin: "12px auto 0" }} onClick={onClose}>Cancel</button>
      </div>
    </div>
  );
}

function AuthModal({ onClose, onSignUp, hasBackend, authError }) {
  const [email, setEmail] = useState("");
  const [pw, setPw] = useState("");
  const [pw2, setPw2] = useState("");        // confirm password (signup only)
  const [showPw, setShowPw] = useState(false); // show/hide password text
  const [mode, setMode] = useState("signin"); // signin | signup | forgotpw | forgotuser
  const [sent, setSent] = useState(false);
  const [busy, setBusy] = useState(false);
  const [resetErr, setResetErr] = useState(null);
  const [noAcct, setNoAcct] = useState(false);      // the address they typed has no account
  const [userFound, setUserFound] = useState(null); // "Forgot username" result: true / false / null (declined)
  // Ask the server for a real reset email. This button used to just flip `sent` and tell the user a link
  // was on its way — no request was ever made, so anyone who forgot their password was locked out for good.
  const sendReset = async () => {
    setResetErr(null); setNoAcct(false); setBusy(true);
    try {
      if (!hasBackend) { setResetErr("Password reset needs the live site — you're on a local demo build."); return; }
      await api.forgotPassword(email.trim().toLowerCase());
      setSent(true);
    } catch (e) {
      // ⭐ AN ADDRESS WITH NO ACCOUNT NOW SAYS SO. Trey: "If they put in an email that doesn't have an
      //   account, can you share an error that says that email doesn't exist with an account." It gets its
      //   own state rather than the red error line, because the useful next step is "create one", not
      //   "try again".
      if (e && e.data && e.data.code === "NO_ACCOUNT") { setNoAcct(true); return; }
      setResetErr((e && e.data && e.data.error) || (e && e.message) || "Couldn't start a reset. Try again in a moment.");
    } finally { setBusy(false); }
  };
  // ⭐ "FORGOT USERNAME" WAS A DEAD BUTTON — the same bug the reset flow had before 22a: it flipped a local
  // flag and claimed "we've sent its sign-in details there" without ever making a request. The username on
  // this site IS the email, so there is nothing to mail; the honest version says whether that address has
  // an account and sends you to the right door.
  const lookupUser = async () => {
    setResetErr(null); setUserFound(null); setBusy(true);
    try {
      if (!hasBackend) { setResetErr("Looking up an account needs the live site — you're on a local demo build."); return; }
      setUserFound(await api.accountExists(email.trim().toLowerCase()));
    } catch (e) {
      setResetErr((e && e.data && e.data.error) || (e && e.message) || "Couldn't look that up. Try again in a moment.");
    } finally { setBusy(false); }
  };
  const title = mode === "signup" ? "Create your account" : mode === "forgotpw" ? "Reset your password" : mode === "forgotuser" ? "Find your username" : "Sign in";
  const pwMismatch = mode === "signup" && pw2.length > 0 && pw !== pw2;
  const canSubmit = email.includes("@") && pw.length >= 6 && (mode !== "signup" || pw === pw2);
  const submit = async () => { if (!canSubmit) return; setBusy(true); try { await onSignUp(email, pw, mode); } finally { setBusy(false); } };
  // a small reusable eye button for the password fields
  const EyeBtn = () => (
    <button type="button" tabIndex={-1} onClick={() => setShowPw((s) => !s)} aria-label={showPw ? "Hide password" : "Show password"}
      style={{ position: "absolute", right: 8, top: "50%", transform: "translateY(-50%)", background: "none", border: "none", color: "var(--mut)", cursor: "pointer", padding: 4, lineHeight: 0 }}>
      <i className={`ti ${showPw ? "ti-eye-off" : "ti-eye"}`} style={{ fontSize: 16 }} aria-hidden="true" />
    </button>
  );
  return (
    <div className="modalbg" onClick={onClose}>
      <div className="panel" style={{ maxWidth: 380, width: "100%", padding: 22 }} onClick={(e) => e.stopPropagation()}>
        <div className="disp" style={{ fontSize: 20, fontWeight: 700, marginBottom: 4 }}>{title}</div>

        {(mode === "signin" || mode === "signup") && <>
          <div className="mut" style={{ fontSize: 12, marginBottom: 14 }}>{hasBackend ? "Your account is secured with hashed credentials." : "Demo mode — accounts are stored locally in your browser. Connect the backend for real accounts."}</div>
          <input className="gs" style={{ width: "100%", marginBottom: 8 }} placeholder="Email" value={email} onChange={(e) => setEmail(e.target.value)} />
          <div style={{ position: "relative", marginBottom: mode === "signup" ? 8 : 14 }}>
            <input className="gs" type={showPw ? "text" : "password"} style={{ width: "100%", paddingRight: 34 }} placeholder="Password" value={pw} onChange={(e) => setPw(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter" && canSubmit) submit(); }} />
            <EyeBtn />
          </div>
          {mode === "signup" && <>
            <div style={{ position: "relative", marginBottom: 6 }}>
              <input className="gs" type={showPw ? "text" : "password"} style={{ width: "100%", paddingRight: 34, borderColor: pwMismatch ? "var(--red)" : undefined }} placeholder="Confirm password" value={pw2} onChange={(e) => setPw2(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter" && canSubmit) submit(); }} />
              <EyeBtn />
            </div>
            {pwMismatch && <div style={{ color: "var(--red)", fontSize: 11.5, marginBottom: 8 }}>Passwords don't match</div>}
            {!pwMismatch && <div style={{ height: 6 }} />}
          </>}
          {authError && <div style={{ color: "var(--red)", fontSize: 12, marginBottom: 10 }}>{authError}</div>}
          <button className="btn btn-gold" style={{ width: "100%", padding: 10 }} disabled={busy || !canSubmit} onClick={submit}>{busy ? "…" : mode === "signup" ? "Create account" : "Sign in"}</button>
          <div style={{ display: "flex", justifyContent: "space-between", marginTop: 10, gap: 8, flexWrap: "wrap" }}>
            {mode === "signin"
              ? <button className="btn-link" style={{ background: "none", border: "none", color: "var(--gold)", fontSize: 11.5, cursor: "pointer", fontFamily: "inherit", padding: 0 }} onClick={() => { setMode("signup"); setPw(""); setPw2(""); }}>Need an account? Sign up</button>
              : <button className="btn-link" style={{ background: "none", border: "none", color: "var(--gold)", fontSize: 11.5, cursor: "pointer", fontFamily: "inherit", padding: 0 }} onClick={() => { setMode("signin"); setPw2(""); }}>Have an account? Sign in</button>}
            {mode === "signin" && <span style={{ display: "flex", gap: 8 }}>
              <button className="btn-link" style={{ background: "none", border: "none", color: "var(--mut)", fontSize: 11.5, cursor: "pointer", fontFamily: "inherit", padding: 0 }} onClick={() => { setSent(false); setNoAcct(false); setResetErr(null); setMode("forgotpw"); }}>Forgot password?</button>
              <button className="btn-link" style={{ background: "none", border: "none", color: "var(--mut)", fontSize: 11.5, cursor: "pointer", fontFamily: "inherit", padding: 0 }} onClick={() => { setSent(false); setUserFound(null); setResetErr(null); setMode("forgotuser"); }}>Forgot username?</button>
            </span>}
          </div>
        </>}

        {mode === "forgotpw" && <>
          <div className="mut" style={{ fontSize: 12.5, marginBottom: 14, lineHeight: 1.5 }}>Enter your account email and we'll send a secure password-reset link. The link expires in 30 minutes.</div>
          {sent ? (
            <div className="panel" data-resetsent="1" style={{ padding: 14, background: "var(--panel2)", textAlign: "center" }}>
              <i className="ti ti-mail-check" style={{ fontSize: 22, color: "var(--green)" }} aria-hidden="true" />
              <div style={{ fontSize: 13, marginTop: 6 }}>A reset link is on its way to <b>{email || "that email"}</b>. Check your inbox and spam — it expires in 30 minutes.</div>
            </div>
          ) : noAcct ? (
            <div className="panel" data-noaccount="1" style={{ padding: 14, background: "var(--panel2)", border: "1px solid var(--gold)" }}>
              <div style={{ fontSize: 13, lineHeight: 1.5 }}>
                <b style={{ color: "var(--gold)" }}>No account for {email}. </b>
                There's no Fantasy Draft Compass account with that address, so there's nothing to reset. Check the spelling — or create an account with it.
              </div>
              <div style={{ display: "flex", gap: 8, marginTop: 11, flexWrap: "wrap" }}>
                <button className="btn btn-mini" onClick={() => { setNoAcct(false); }}>Try another email</button>
                <button className="btn btn-mini btn-gold" onClick={() => { setNoAcct(false); setSent(false); setMode("signup"); setPw(""); setPw2(""); }}>Create an account</button>
              </div>
            </div>
          ) : <>
            <input className="gs" style={{ width: "100%", marginBottom: 12 }} placeholder="Email" value={email} onChange={(e) => setEmail(e.target.value)}
              onKeyDown={(e) => { if (e.key === "Enter" && email.includes("@") && !busy) sendReset(); }} />
            <button className="btn btn-gold" style={{ width: "100%", padding: 10 }} disabled={busy || !email.includes("@")} onClick={sendReset}>{busy ? "Sending…" : "Send reset link"}</button>
            {resetErr && <div data-reseterr="1" style={{ color: "var(--red)", fontSize: 12, marginTop: 10, lineHeight: 1.45 }}>{resetErr}</div>}
          </>}
          <button className="btn-link" style={{ background: "none", border: "none", color: "var(--gold)", fontSize: 11.5, cursor: "pointer", fontFamily: "inherit", padding: 0, marginTop: 10, display: "block", margin: "10px auto 0" }} onClick={() => setMode("signin")}>← Back to sign in</button>
        </>}

        {mode === "forgotuser" && <>
          <div className="mut" style={{ fontSize: 12.5, marginBottom: 14, lineHeight: 1.5 }}>Your username <b>is</b> the email you signed up with — there's nothing separate to look up. Enter an address and we'll tell you whether an account exists for it.</div>
          {userFound === true ? (
            <div className="panel" data-userfound="1" style={{ padding: 14, background: "var(--panel2)" }}>
              <div style={{ fontSize: 13, lineHeight: 1.5 }}><b style={{ color: "var(--green)" }}>That's an account. </b>Sign in with <b>{email}</b> as your username. If you don't remember the password, reset it.</div>
              <div style={{ display: "flex", gap: 8, marginTop: 11, flexWrap: "wrap" }}>
                <button className="btn btn-mini btn-gold" onClick={() => { setUserFound(null); setMode("signin"); }}>Back to sign in</button>
                <button className="btn btn-mini" onClick={() => { setUserFound(null); setSent(false); setNoAcct(false); setMode("forgotpw"); }}>Reset the password</button>
              </div>
            </div>
          ) : userFound === false ? (
            <div className="panel" data-usermissing="1" style={{ padding: 14, background: "var(--panel2)", border: "1px solid var(--gold)" }}>
              <div style={{ fontSize: 13, lineHeight: 1.5 }}><b style={{ color: "var(--gold)" }}>No account for {email}. </b>Nothing is registered to that address — check the spelling, or create an account with it.</div>
              <div style={{ display: "flex", gap: 8, marginTop: 11, flexWrap: "wrap" }}>
                <button className="btn btn-mini" onClick={() => setUserFound(null)}>Try another email</button>
                <button className="btn btn-mini btn-gold" onClick={() => { setUserFound(null); setMode("signup"); setPw(""); setPw2(""); }}>Create an account</button>
              </div>
            </div>
          ) : userFound === null && resetErr ? (
            <>
              <input className="gs" style={{ width: "100%", marginBottom: 12 }} placeholder="Email to look up" value={email} onChange={(e) => setEmail(e.target.value)} />
              <button className="btn btn-gold" style={{ width: "100%", padding: 10 }} disabled={busy || !email.includes("@")} onClick={lookupUser}>{busy ? "Checking…" : "Check this email"}</button>
              <div data-reseterr="1" style={{ color: "var(--red)", fontSize: 12, marginTop: 10, lineHeight: 1.45 }}>{resetErr}</div>
            </>
          ) : <>
            <input className="gs" style={{ width: "100%", marginBottom: 12 }} placeholder="Email to look up" value={email} onChange={(e) => setEmail(e.target.value)}
              onKeyDown={(e) => { if (e.key === "Enter" && email.includes("@") && !busy) lookupUser(); }} />
            <button className="btn btn-gold" style={{ width: "100%", padding: 10 }} disabled={busy || !email.includes("@")} onClick={lookupUser}>{busy ? "Checking…" : "Check this email"}</button>
          </>}
          <button className="btn-link" style={{ background: "none", border: "none", color: "var(--gold)", fontSize: 11.5, cursor: "pointer", fontFamily: "inherit", padding: 0, marginTop: 10, display: "block", margin: "10px auto 0" }} onClick={() => setMode("signin")}>← Back to sign in</button>
        </>}
      </div>
    </div>
  );
}

function Checkout({ biz, user, onDone, onBack, canceled }) {
  const [method, setMethod] = useState("card");
  const [promo, setPromo] = useState("");
  const [applied, setApplied] = useState(null);
  const [busy, setBusy] = useState(false);
  const [payErr, setPayErr] = useState(null);
  const price = applied ? +(biz.price * (1 - applied.pct / 100)).toFixed(2) : biz.price;
  const tryPromo = () => { const f = biz.promos.find((p) => p.code.toLowerCase() === promo.trim().toLowerCase()); setApplied(f || null); if (!f) setPromo(""); };
  // onDone hands off to Stripe and throws if it can't. Catching it HERE is the point: the buyer has to see
  // that nothing happened, rather than the app quietly deciding they've paid.
  const pay = async () => {
    setPayErr(null); setBusy(true);
    try { await onDone(); }
    catch (e) {
      setPayErr((e && e.data && e.data.error) || (e && e.message) || "We couldn't open the payment page. Nothing has been charged — please try again.");
      setBusy(false);
    }
  };
  // When a real backend is connected, checkout hands off to Stripe (onDone -> startCheckout ->
  // redirect). We don't show the simulated card form in that case.
  if (hasBackend) {
    return (
      <div style={{ maxWidth: 480, margin: "0 auto", padding: "50px 20px" }}>
        <button className="btn btn-mini" onClick={onBack}>← Back</button>
        <div className="panel" style={{ padding: 24, marginTop: 14 }}>
          <div className="disp" style={{ fontSize: 22, fontWeight: 700 }}>Season pass checkout</div>
          <div className="mut" style={{ fontSize: 12.5, margin: "4px 0 16px" }}>{user.email} • valid through March 1</div>
          {canceled && (
            <div style={{ marginBottom: 14, padding: "10px 12px", borderRadius: 8, border: "1px solid var(--line2)", background: "var(--panel2)" }}>
              <div style={{ fontSize: 12.5, fontWeight: 700, marginBottom: 2 }}>No problem — nothing was charged.</div>
              <div className="mut" style={{ fontSize: 12, lineHeight: 1.5 }}>You came back before finishing. Your account is still here; pick up where you left off whenever you're ready.</div>
            </div>
          )}
          <div style={{ display: "flex", justifyContent: "space-between", padding: "10px 0", borderBottom: "1px solid var(--line)" }}>
            <span>Fantasy Draft Compass season pass</span><b className="num">${biz.price.toFixed(2)}</b>
          </div>
          <div className="mut" style={{ fontSize: 12.5, margin: "14px 0 16px" }}>You'll be taken to our secure payment page to finish. Your card details are handled entirely by Stripe — they never touch our servers.</div>
          <button className="btn btn-gold" style={{ width: "100%", padding: 12, fontSize: 15 }} onClick={pay} disabled={busy}>{busy ? "Taking you to checkout…" : `Continue to payment — $${biz.price.toFixed(2)}`}</button>
          {payErr && (
            <div style={{ marginTop: 12, padding: "10px 12px", borderRadius: 8, border: "1px solid var(--red)", background: "rgba(232,99,90,.08)" }}>
              <div style={{ color: "var(--red)", fontSize: 12.5, fontWeight: 700, marginBottom: 3 }}>Payment couldn't be started</div>
              <div className="mut" style={{ fontSize: 12, lineHeight: 1.5 }}>{payErr} If it keeps happening, hit <b style={{ color: "var(--ink)" }}>Report a bug</b> and we'll sort it out — you have not been charged.</div>
            </div>
          )}
        </div>
      </div>
    );
  }
  const paySim = () => { setBusy(true); setTimeout(onDone, 900); };
  return (
    <div style={{ maxWidth: 480, margin: "0 auto", padding: "50px 20px" }}>
      <button className="btn btn-mini" onClick={onBack}>← Back</button>
      <div className="panel" style={{ padding: 24, marginTop: 14 }}>
        <div className="disp" style={{ fontSize: 22, fontWeight: 700 }}>Season pass checkout</div>
        <div className="mut" style={{ fontSize: 12.5, margin: "4px 0 16px" }}>{user.email} • valid through March 1</div>
        <div style={{ display: "flex", justifyContent: "space-between", padding: "10px 0", borderBottom: "1px solid var(--line)" }}>
          <span>Fantasy Draft Compass season pass</span><b className="num">${price.toFixed(2)}</b>
        </div>
        {applied && <div className="mut" style={{ fontSize: 12, padding: "6px 0", color: "var(--green)" }}>Promo "{applied.code}" applied — {applied.pct}% off</div>}
        <div style={{ display: "flex", gap: 8, margin: "12px 0" }}>
          <input className="gs" style={{ flex: 1 }} placeholder="Promo code" value={promo} onChange={(e) => setPromo(e.target.value)} />
          <button className="btn" onClick={tryPromo}>Apply</button>
        </div>
        <div style={{ display: "flex", gap: 8, margin: "4px 0 14px" }}>
          {[["card","Card"],["paypal","PayPal"],["venmo","Venmo"]].map(([k, l]) => (
            <button key={k} className="btn" style={{ flex: 1, borderColor: method === k ? "var(--gold)" : "var(--line)" }} onClick={() => setMethod(k)}>{l}</button>
          ))}
        </div>
        {method === "card" ? (
          <div className="panel" style={{ padding: 14, background: "var(--panel2)", marginBottom: 14 }}>
            <div className="mut" style={{ fontSize: 11.5, marginBottom: 8 }}>Secure card form — embedded directly from the payment processor. In production this iframe belongs to them; your card number never reaches our servers.</div>
            <input className="gs" style={{ width: "100%", marginBottom: 6 }} placeholder="Card number (simulated — don't enter a real card)" disabled />
            <div style={{ display: "flex", gap: 6 }}>
              <input className="gs" style={{ flex: 1 }} placeholder="MM/YY" disabled /><input className="gs" style={{ flex: 1 }} placeholder="CVC" disabled /><input className="gs" style={{ flex: 1 }} placeholder="ZIP" disabled />
            </div>
          </div>
        ) : (
          <div className="panel" style={{ padding: 14, background: "var(--panel2)", marginBottom: 14 }}>
            <div className="mut" style={{ fontSize: 12 }}>In production this button hands off to {method === "paypal" ? "PayPal" : "Venmo (via PayPal)"} — you approve there and return here with the pass active. Nothing financial is stored on our side.</div>
          </div>
        )}
        <button className="btn btn-gold" style={{ width: "100%", padding: 12, fontSize: 15 }} onClick={paySim} disabled={busy}>{busy ? "Processing…" : `Complete purchase — $${price.toFixed(2)} (simulated)`}</button>
      </div>
    </div>
  );
}

